(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.3)*20 + Math.cos(y*0.012-t*0.2)*15;
  const w1y = Math.cos(y*0.015-t*0.25)*20 + Math.sin(x*0.013+t*0.35)*15;
  const w2x = Math.sin((x+w1x)*0.025-t*0.5)*8 + Math.cos((y+w1y)*0.02+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.025+t*0.45)*8 + Math.sin((x+w1x)*0.022-t*0.35)*6;
  const w3x = Math.sin((x+w2x)*0.04+t*0.7)*4;
  const w3y = Math.cos((y+w2y)*0.04-t*0.6)*4;
  const sx = x+w1x+w2x+w3x, sy = y+w1y+w2y+w3y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*110, 120+Math.cos(t*0.65+4)*70, 0.11, 2.1, 1.05],
    [400+Math.cos(t*0.55+2)*70, 180+Math.sin(t*0.75+1)*90, 0.065, 1.8, 0.85],
    [200+Math.sin(t*0.38+6)*130, 40+Math.cos(t*0.48+3)*60, 0.095, 2.4, 1.15],
    [300+Math.cos(t*0.42+7)*90, 220+Math.sin(t*0.58+5)*50, 0.075, 2.0, 0.9]
  ];
  let aS=0, iS=0, cross=0;
  for(let i=0;i<src.length;i++){
    for(let j=i+1;j<src.length;j++){
      const [ax,ay,af,asp,aw]=src[i],[bx,by,bf,bsp,bw]=src[j];
      const da=Math.sqrt((sx-ax)**2+(sy-ay)**2), db=Math.sqrt((sx-bx)**2+(sy-by)**2);
      const wa=Math.sin(da*af-t*asp)*aw, wb=Math.sin(db*bf-t*bsp)*bw;
      cross+=wa*wb*0.08;
    }
    const [sX,sY,f,sp,w]=src[i];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    aS+=wave*w;
    iS+=Math.sin(d*f*0.65+t*sp*0.55+1.5)*w;
  }
  const n=src.length;
  const act=aS/n, inh=iS/n, cr=cross/(n*(n-1)*0.5);
  const turb1=(Math.sin(sx*0.035+sy*0.022+t*0.8)+Math.sin(sx*0.028-sy*0.038+t*1.1))/2;
  const turb2=(Math.sin((sx+sy)*0.1+t*2.5)+Math.sin((sx-sy)*0.08-t*2.0))*0.3;
  const turb3=Math.sin(sx*0.07*Math.cos(t*0.2)+sy*0.05*Math.sin(t*0.3)+t*1.8)*0.2;
  const bg=turb1+turb2+turb3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.5)+Math.sin(dist*0.035+ang*4.5-t*1.2)+Math.sin(dist*0.06-ang*2-t*2.0))*0.3;
  const turingFeed=0.035+Math.sin(t*0.15)*0.01;
  const turingKill=0.06+Math.cos(t*0.12)*0.015;
  const localFeed=turingFeed+Math.sin(sx*0.008+sy*0.006)*0.005;
  const localKill=turingKill+Math.cos(sx*0.007-sy*0.009)*0.005;
  const reaction=act-inh*0.7+bg*0.25+spiral+cr;
  const turing=Math.tanh((reaction*localKill/(localFeed+Math.abs(reaction)*0.1))*2.5);
  const laplacian=(Math.sin(sx*0.16)*Math.sin(sy*0.16)+Math.sin((sx+sy)*0.11+t)*0.5+Math.sin((sx*0.5-sy*0.7)*0.08+t*0.7)*0.3);
  const cell=Math.tanh(laplacian*1.8)*0.35;
  const edge=Math.abs(turing)>0.65?Math.pow(Math.abs(turing),0.6)*0.4:0;
  const blend=turing*0.55+cell*0.2+edge*0.25;
  const v=blend*0.5+0.5;
  const glow=Math.exp(-Math.abs(blend)*1.5)*0.15;
  const vGlow=Math.min(1,v+glow);
  const pal=[[5,12,52],[12,42,88],[18,78,112],[25,125,130],[45,160,118],[140,178,80],[198,178,55],[218,145,62],[208,100,65],[175,60,72],[120,35,62],[65,22,55],[5,12,52]];
  const idx=vGlow*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(turing*Math.PI*1.2)*0.18;
  const highlight=edge>0.15?1.0+edge*0.3:1.0;
  const depth=1.0+Math.sin(dist*0.008-t*0.3)*0.08;
  const finalMult=lum*highlight*depth;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*finalMult)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*finalMult)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*finalMult)|0
  ];
}
